import path from 'node:path';
import { test, expect } from '@playwright/test';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });

test.describe('Экран «מכשירים»', () => {
  test('«מכשירים» показывает только подключённые устройства, число = лимит #8b11bf53 @iphone @prod-safe', async ({ page }) => {
    // 1. Open /account/devices
    await page.goto('https://banci.expo.app/account/devices');

    // 2. Wait for the device list
    const limitMessage = page.getByText('הגעתם למספר הטלפונים המרבי');
    await expect(limitMessage.first()).toBeVisible();

    // Expected: exactly 2 device rows (connected phones)
    const rows = page.getByRole('button', { name: /, מחובר$/ });
    await expect(rows).toHaveCount(2);

    // Expected: no "לא מחובר" text
    await expect(page.getByText('לא מחובר', { exact: true })).toHaveCount(0);

    // Expected: limit message contains 2
    await expect(limitMessage.first()).toContainText('(2)');
  });
});
